pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IERC721Probe {
    function balanceOf(address owner) external view returns (uint256);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseToken,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        vm.assume(baseToken != address(0));
        feeRate = uint16(bound(feeRate, 0, 5_000));

        // The pool must be initialized with a live ERC721 token contract.
        MockNFT nft = new MockNFT();

        c.initialize(
            baseToken,
            address(nft),
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after initialize, c.nft() is the token contract the pool
        // was given, so an ERC721 view call against c.nft() must NOT revert.
        bool ok;
        try IERC721Probe(c.nft()).balanceOf(address(c)) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract MockNFT {
    mapping(address => uint256) public balanceOfOverride;

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }
}

